WITH thread_info AS MATERIALIZED ( SELECT t.id AS thread_id, t.link_id, LOWER(SPLIT_PART(link.email_address, '@', 2)) AS user_domain FROM email_threads t JOIN email_links link ON link.id = t.link_id WHERE t.id = $1 ) SELECT a.id AS attachment_db_id, m.provider_id as email_provider_id, a.provider_attachment_id as provider_attachment_id, a.filename as filename, a.mime_type as mime_type, m.internal_date_ts as internal_date_ts, m.id as message_db_id, m.thread_id as thread_db_id, from_contact.email_address as sender_email, m.subject as subject FROM email_attachments a JOIN email_messages m ON a.message_id = m.id JOIN email_contacts from_contact ON m.from_contact_id = from_contact.id JOIN thread_info ti ON m.thread_id = ti.thread_id WHERE m.thread_id = $1 AND a.filename IS NOT NULL -- attachment mime type filters injected below AND a.reference_url IS NULL AND ( a.mime_type IN ( 'application/pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword', 'text/html', 'text/plain', 'pdf' ) OR ( a.mime_type = 'application/octet-stream' AND UPPER(SUBSTRING(a.filename FROM '\.([^.]+)$')) IN ('PDF', 'DOC', 'DOCX', 'TXT', 'HTML') ) ) AND ( -- condition 1: the thread contains a sent message EXISTS ( SELECT 1 FROM email_messages sent_message WHERE sent_message.thread_id = ti.thread_id AND sent_message.is_sent = true ) -- condition 2: the thread contains provider-important correspondence OR EXISTS ( SELECT 1 FROM email_messages labeled_message JOIN email_message_mailbox_facts mf ON mf.id = labeled_message.id WHERE labeled_message.thread_id = ti.thread_id AND mf.is_present AND NOT mf.in_trash AND mf.provider_is_important ) -- conditions 3 and 4 share one sender pass OR EXISTS ( SELECT 1 FROM email_messages sender_message JOIN email_contacts c ON c.id = sender_message.from_contact_id WHERE sender_message.thread_id = ti.thread_id AND ( LOWER(SPLIT_PART(c.email_address, '@', 2)) = ti.user_domain -- whitelisted domain check injected below OR ( -- condition 4: email from whitelisted domain c.email_address IS NOT NULL AND LOWER(SPLIT_PART(c.email_address, '@', 2)) IN ( 'docusign.com', 'hellosign.com', 'dropboxsign.com', 'adobesign.com', 'signnow.com', 'pandadoc.com', 'quickbooks.com', 'xero.com', 'stripe.com', 'paypal.com', 'squareup.com', 'bill.com', 'gusto.com', 'justworks.com', 'rippling.com', 'intuit.com', 'chase.com', 'bankofamerica.com', 'wellsfargo.com', 'capitalone.com', 'amex.com', 'citibank.com', 'robinhood.com', 'etrade.com', 'fidelity.com', 'schwab.com', 'interactivebrokers.com', 'vanguard.com', 'plaid.com', 'irs.gov', 'ssa.gov', 'uscis.gov', 'treasury.gov', 'efiletexas.gov', 'efilemanager.com', 'efile.ca.gov', 'sec.gov', 'greenhouse.io', 'lever.co', 'bamboohr.com', 'workday.com', 'sap.com', 'indeed.com', 'linkedin.com', 'ziprecruiter.com', 'docusign.net', 'dropbox.com', 'box.com', 'drive.google.com', 'sharepoint.com', 'onedrive.live.com', 'wetransfer.com', 'figma.com', 'canva.com', 'notion.so', 'clickup.com', 'airtable.com', 'unitedhealthcare.com', 'aetna.com', 'cigna.com', 'metlife.com', 'anthem.com', 'oscarhealth.com', 'delta-dental.com', 'vanguardbenefits.com', 'fidelitybenefits.com', 'aws.amazon.com', 'cloudflare.com', 'digitalocean.com', 'github.com', 'gitlab.com', 'atlassian.com', 'openai.com', 'anthropic.com' ) ) ) ) ) ORDER BY a.id
